<div class="container footer-grid"><?php for ( $i = 1; $i <= 4; $i++ ) { ?><div class="footer-column"><?php if ( 1 === $i ) { if ( get_theme_mod( 'kimpu_footer_logo', true ) ) { ?><a class="footer-brand" href="<?php echo esc_url( home_url( '/' ) ); ?>"><?php echo esc_html( get_bloginfo( 'name' ) ); ?></a><?php } ?><p><?php echo esc_html( get_theme_mod( 'kimpu_footer_description', get_bloginfo( 'description' ) ) ); ?></p><?php kimpu_render_social_links(); ?><?php } elseif ( is_active_sidebar( 'footer-' . $i ) ) { dynamic_sidebar( 'footer-' . $i ); } elseif ( 2 === $i ) { ?><h2><?php esc_html_e( 'Quick Links', 'kimpu-multipurpose' ); ?></h2><?php wp_nav_menu( array( 'theme_location' => 'footer', 'container' => false, 'fallback_cb' => false ) ); ?><?php } elseif ( 3 === $i ) { ?><h2><?php esc_html_e( 'Explore', 'kimpu-multipurpose' ); ?></h2><?php wp_nav_menu( array( 'theme_location' => 'footer', 'container' => false, 'fallback_cb' => false ) ); ?><?php } else { ?><h2><?php esc_html_e( 'Contact', 'kimpu-multipurpose' ); ?></h2><?php if ( get_theme_mod( 'kimpu_contact_email' ) ) { ?><p><a href="mailto:<?php echo esc_attr( sanitize_email( get_theme_mod( 'kimpu_contact_email' ) ) ); ?>"><?php echo esc_html( get_theme_mod( 'kimpu_contact_email' ) ); ?></a></p><?php } ?><?php if ( get_theme_mod( 'kimpu_contact_phone' ) ) { ?><p><?php echo esc_html( get_theme_mod( 'kimpu_contact_phone' ) ); ?></p><?php } ?><?php if ( get_theme_mod( 'kimpu_contact_address' ) ) { ?><p><?php echo esc_html( get_theme_mod( 'kimpu_contact_address' ) ); ?></p><?php } ?><?php } ?></div><?php } ?></div><div class="container footer-bottom"><span><?php echo esc_html( get_theme_mod( 'kimpu_footer_copyright', '© ' . date_i18n( 'Y' ) . ' ' . get_bloginfo( 'name' ) ) ); ?></span><?php wp_nav_menu( array( 'theme_location' => 'footer', 'container' => false, 'depth' => 1, 'fallback_cb' => false ) ); ?></div>
